state=normalizeGame(state);advanceSeries(state);
const paths={gasmask:'M5 12V8a7 7 0 0 1 14 0v4M6 10a3 3 0 1 1 6 0 3 3 0 0 1-6 0Zm6 0a3 3 0 1 1 6 0 3 3 0 0 1-6 0ZM5 13c-3 0-4 2-3 5l2 3h3l1-5-3-3Zm14 0c3 0 4 2 3 5l-2 3h-3l-1-5 3-3ZM8 14l2 3h4l2-3M10 17v4h4v-4M3 16h3m12 0h3M5 5l2-2m10 0 2 2',filter:'M5 7h14v12H5zM8 3h8v4M8 11h8m-8 4h8',stimulant:'M7 3h10v4l-2 3v10H9V10L7 7V3ZM9 14h6M12 11v6',grenade:'M9 7V4h6v3M15 4l4 2M17 14a5 7 0 1 1-10 0 5 7 0 0 1 10 0ZM9 11h6',science:'M9 3h6M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3M8 14h8',station:'M3 21V11a9 9 0 0 1 18 0v10M7 21V11a5 5 0 0 1 10 0v10M3 21h18M11 11h2v8h-2',heroes:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bag:'M6 7h12l2 14H4L6 7ZM9 7V4h6v3M8 12h8v5H8',shop:'M3 9h18M5 9v12h14V9M2 4h20l-2 5H4L2 4ZM9 21v-7h6v7',tool:'M14 6a5 5 0 0 0-6 6l-5 5a2 2 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-3 3-3-3 3-3',knife:'m4 20 5-5m-3 3 2 2m0-7L19 2c2 7-3 12-9 13L8 13Z',jacket:'m8 3-5 5v7l3-1v7h12v-7l3 1V8l-5-5-4 4-4-4ZM12 7v14M8 3v6m8-6v6',medical:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6V3Z',metal:'m3 6 7-3 6 3 5-1-2 7 2 6-7 3-6-2-5 1 2-7-2-7ZM7 10l6-3 4 4-4 6-5-2Z',meat:'M17 3c5 2 5 7 1 11-3 3-7 4-10 1l-3 4a2 2 0 1 1-3-3l4-3C3 8 11 1 17 3Z',tooth:'M6 3c-5 4 0 10 1 16 1 5 4 0 5-4 1 4 4 9 5 4 1-6 6-12 1-16-3-2-4 0-6 0S9 1 6 3Z',leather:'m7 3 4 2 5-3 3 5-1 5 3 5-5 1-3 4-5-3-5 1 1-6-2-5 5-6Z',gun:'M3 7h18v6H10v7H5v-7H3V7ZM10 13h5l-1 4h-4M18 7V4',ammo:'M9 4 12 1l3 3v16H9V4Zm0 12h6M7 23h10',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',lock:'M5 10h14v11H5V10Zm3 0V6a4 4 0 0 1 8 0v4',rat:'M3 15c-4-6 3-9 8-6l4-2 3 4 3 3-3 3H8c-4 0-6 6-7 2m8-3-1 4m8-4 1 4M11 9c-1-6 6-7 6-2',info:'M12 11v6M12 7v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',heart:'M20 4c-4-3-8 2-8 2S8 1 4 4c-7 6 8 17 8 17S27 10 20 4Z',check:'m5 12 4 4L19 6',rest:'M4 4v17M4 14h17v7M4 8h5v6H4Zm5 2h12v4H9',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16'};
Object.assign(paths,{
 pistol:'M3 6h17v6H10l-2 8H3l2-8H3V6ZM10 12h5l-1 4H9M17 6V4M5 9h12',
 smg:'M4 7h13v6H4V7ZM17 8h5v3h-5M8 13v8h4v-8M4 9H1v8h3M6 7V4h5v3M12 13h4v4h-4M7 10h6',
 assaultRifle:'M2 8l5 2h8l2-2h4v4h-6l-2 2H7l-5 3V8ZM21 9h2M9 14l-1 6h3l2-6M15 13c0 3 1 5 3 7l3-2c-2-2-3-3-3-5M7 8h7M19 8V5M6 10v4',
 rifle:'M1 14l5-4h5l2-2h10M6 12h8l2-2h7M7 12l-2 6H1v-4M11 12l-1 4h4v-4M10 8V5h5v3M19 8v2',
 heavyWeapon:'M2 7h6v11H2V7ZM8 8h11M8 10h12M8 12h12M8 14h12M8 16h11M20 7c3 0 3 11 0 11s-3-11 0-11ZM11 7v11M16 7v11M4 7V4h6v4M5 18v3',
 shotgun:'M2 12l5-4h16M7 11h16M7 11l-2 7H1v-5M10 11v5h4v-5M17 8v3'
});
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]??paths.bag}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const money=n=>n==null?'—':(n/10).toLocaleString('ru-RU',{maximumFractionDigits:1});
const num=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:1});
const sec=at=>Math.max(0,Math.ceil((at-Date.now())/1000));
const btn=(text,action,extra='',className='')=>`<button class="btn ${className}" data-action="${action}" ${extra}>${text}</button>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageWorks=true;}catch{storageWorks=false;toast('Браузер не сохраняет прогресс. Экспортируй сохранение через меню.');}}
function craftResultEffect(success,quality=false){
 document.querySelectorAll('.craft-result-effect').forEach(el=>el.remove());
 const effect=document.createElement('div');effect.className='craft-result-effect '+(success?'craft-success':'craft-failure')+(quality?' craft-quality':'');effect.setAttribute('aria-hidden','true');
 if(success){for(let burst=0;burst<(quality?5:3);burst++)for(let i=0;i<(quality?20:12);i++){
  const spark=document.createElement('i'),angle=2*Math.PI*i/(quality?20:12),distance=(quality?90:45)+(i%3)*(quality?25:15);
  spark.style.cssText=`--x:${Math.cos(angle)*distance}px;--y:${Math.sin(angle)*distance}px;--delay:${burst*90}ms;--left:${quality?15+burst*17:35+burst*15}%;--top:${quality?12+(burst%2)*8:38+(burst%2)*12}%;--spark:${['#a8d9ad','#e5cc85','#cedbd0'][i%3]}`;effect.append(spark);
 }}
 document.body.append(effect);setTimeout(()=>effect.remove(),quality?1500:success?1100:600);
}
function toast(text){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.className='toast';el.textContent=text;toastTimer=setTimeout(()=>{el.className='';el.textContent='';},4200);}
function commit(action,success=''){
 try{
  const next=act(state,action);
  if(['claimCraft','retryUpgrade'].includes(action.type)&&next.productions[action.production].level>state.productions[action.production].level){
   const id=action.production;
   productionLevelEffects.add(id);
   setTimeout(()=>{
    productionLevelEffects.delete(id);
    root.querySelector(`.production-tabs [data-production="${id}"]`)?.classList.remove('production-level-up');
   },1200);
  }
  state=next;save();render();if(success)toast(success);return true;
 }catch(error){toast(error.message);return false;}
}
function heroStatus(h=state.hero){if(!h)return 'Нет сталкеров';if(h.dead)return 'Погиб';if(!h.job)return 'Готов к вылазке';if(h.job.kind==='series')return h.job.phase==='break'?`Передышка · ${h.job.completed}/${h.job.total}`:h.job.phase==='done'?(h.job.worker.dead?'Погиб в серии':'Серия завершена'):`${locationName(h.job.location)} · ${h.job.completed+1}/${h.job.total}`;if(ready(h.job))return isCombatRun(h.job)&&!h.job.result.alive?'Погиб на вылазке':'Ожидает решения';return h.job.kind==='rest'?'Отдыхает на станции':h.job.kind==='help'?'Помогает на станции':'На вылазке';}
function jobMeter(job){return `<div class="countdown" data-until="${job.endsAt}">${ready(job)?'Готово':`${sec(job.endsAt)} сек.`}</div><div class="progress"><i data-progress="${job.startedAt},${job.endsAt}" style="width:${Math.min(100,(Date.now()-job.startedAt)/(job.endsAt-job.startedAt)*100)}%"></i></div>`;}
function radiationReport(job){
 const dose=jobRadiation(job);
 return dose?`<p class="note radiation-status">Получено облучение +${dose} РАД.</p>`:'';
}
function health(h){const maxHp=effectiveMaxHp(h),blocked=(h.maxHp-maxHp)/h.maxHp*100;return `<div class="health-label"><span>ЗДОРОВЬЕ${h.radiation?` · <b class="radiation-status">Облучён (${h.radiation})</b>`: ''}</span><span>${num(Math.min(h.hp,maxHp))} / ${num(maxHp)}</span></div><div class="hpbar ${h.hp<maxHp*.3?'low':''}" style="--radiation-blocked:${blocked}%"><i style="width:${Math.max(0,Math.min(h.hp,maxHp)/h.maxHp*100)}%"></i></div>`;}
function heroSummary(h=state.hero){
 if(!h)return `<div class="empty-hero"><div class="portrait dim"></div><div><h3>Станции нужны сталкеры</h3><p>Выбери профессию, имя, национальность и стартовый перк.</p>${btn('Нанять за 50 A','hireModal')}</div></div>`;
 const ref=`data-hero="${esc(h.id)}"`,shownHp=h.job?.kind==='series'?h.job.worker.hp:isCombatJob(h.job?.kind)&&ready(h.job)?h.job.result.hp:h.hp;
 const task=h.job&&!ready(h.job)?`<div class="hero-task"><span>${h.job.kind==='rest'?icon('rest'):icon('map')}${h.job.kind==='series'?(h.job.phase==='break'?'Передышка':locationName(h.job.location)):h.job.kind==='rest'?'Отдых':h.job.kind==='help'?'Помогать на станции':locationName(h.job.kind)}</span><strong data-until="${h.job.endsAt}">${sec(h.job.endsAt)} сек.</strong></div><div class="progress"><i data-progress="${h.job.startedAt},${h.job.endsAt}" style="width:${Math.min(100,(Date.now()-h.job.startedAt)/(h.job.endsAt-h.job.startedAt)*100)}%"></i></div>`:'';
 return `<div class="row">${heroPortrait(h)}<div class="grow"><div class="row between"><h3>${esc(heroTitle(h))}</h3><span class="pill">Ур. ${h.level}</span></div><p class="statusline ${h.job?'busy':''} ${h.dead?'red':''}">${heroStatus(h)}</p></div></div>${health({...h,...(h.job?.kind==='series'?h.job.worker:{}),radiation:(h.radiation??0)+(ready(h.job)?jobRadiation(h.job):0),hp:shownHp})}${heroExperienceBar(h)}${radiationBlocksMissions(h)?'<p class="note radiation-status">Сильное облучение. Чтобы выйти на задание, сними радиацию.</p>':''}${task}${h.job?.kind==='series'&&h.job.phase==='break'?btn('Прервать и получить','stopSeries',ref,'full secondary'):''}<div class="button-row hero-actions">${btn('Статы и снаряжение','heroStats',ref,'secondary')}${h.job?(ready(h.job)?btn('Получить результат','heroJob',ref,firstLocationResult(h)?'first-result':''):h.job.kind==='rest'?btn('Прервать отдых','interruptRest',ref,'secondary'):''):h.dead?btn('Восстановить','reviveModal',ref,'danger'):btn('Отдых','restMenu',ref,'ghost')+btn('На задание','selectHero',ref+(radiationBlocksMissions(h)?' disabled':''),'mission-start')}</div>`;
}
function heroExperienceBar(h){
 const cap=heroLevelCap(h),atCap=h.level>=cap;
 return `<div class="health-label"><span>ОПЫТ${rebirthStars(h)?` · −${rebirthXpPenalty(h)}%`:''}</span><span>${atCap?'ПЕРЕПОДГОТОВКА ДОСТУПНА':num(h.xp)+' / '+100*h.level}</span></div><div class="xpbar ${atCap?'retraining-ready':''}"><i style="width:${atCap?100:Math.min(100,h.xp/(100*h.level)*100)}%"></i>${atCap?btn('Пройти переподготовку','rebirthMenu',`data-hero="${esc(h.id)}" ${h.job||h.dead?'disabled':''}`,'retraining-button'):''}</div>`;
}
function rebirthAppearance(h){return rebirthStars(h)?`reborn reborn-${Math.min(3,rebirthStars(h))}`:'';}
const ATTRIBUTE_NAMES={strength:'Сила',agility:'Ловкость',intelligence:'Интеллект',perception:'Восприятие'};
function rolePortrait(role){return `<span class="role-portrait ${role}" aria-hidden="true"><svg viewBox="0 0 64 76"><path d="M6 76V60q0-18 26-18t26 18v16" fill="${role==='shekel'?'#8e7542':'#526b59'}"/><path d="M17 24q0-22 15-22t15 22v10q0 20-15 20T17 34Z" fill="#cfb896"/><path d="M14 23Q10 0 32 0t18 23L38 12 21 23" fill="${role==='shekel'?'#544331':'#303c33'}"/><path d="M23 30h4m10 0h4m-14 12q5 3 10 0" fill="none" stroke="#493e35" stroke-width="2"/>${role==='shekel'?'<path d="M12 21V10h40v11Z" fill="#5e674d"/>':'<path d="M11 51Q4 0 32 0t21 51l-9-12V22L32 10 20 22v17Z" fill="#49604d"/>'}</svg></span>`;}
function stationRole(){const role=PLAYER_ROLES[state.playerRole];return role?`<div class="station-leader">${rolePortrait(state.playerRole)}<div><strong>${role.title}</strong><small>${role.motto}</small></div></div>`:'';}
function keeperCard(){const q=keeperQuestView(state);return `<div class="card"><div class="row">${icon('station')}<div><h3>Смотритель станции</h3><p class="subtitle">${q.stage>4?'Все текущие поручения выполнены.':q.title}${q.status==='accepted'&&q.stage>1?` · ${q.progress} / ${q.target}`:''}</p></div></div><div class="spacer"></div>${btn(q.stage===3?'Познакомиться':'Задание Смотрителя','toothQuest','','full secondary')}</div>`;}
function heroPortrait(h){const count=availablePerkLevels(h).length;return count?`<button class="portrait small perk-portrait ${h.dead?'dim':''}" data-action="choosePerkMenu" data-hero="${esc(h.id)}" aria-label="Выбрать перк для ${esc(h.name)}: доступно ${count}" title="Доступно выборов перка: ${count}"><span class="perk-plus" aria-hidden="true">+</span></button>`:`<div class="portrait small ${h.dead?'dim':''}"></div>`;}
function heroCombatStats(hero){
 return Object.entries(hero.weapons).filter(([,weapon])=>weapon).map(([slot,weapon])=>{
  const distances=weapon.type==='ranged'?[0,1,2,3].filter(distance=>distance<=(weapon.maxDistance??3)):[0];
  const rows=distances.map(distance=>{
   const stats=heroAttackStats(hero,weapon,distance);
   return `<p>${distance===0?'Вплотную':'Дистанция '+distance}: ${num(stats.accuracy)}% · ${num(stats.min)}–${num(stats.max)} урона${weapon.damageRolls>1?' × '+weapon.damageRolls:''}${stats.attacks>1?' · '+stats.attacks+' атаки за ход':''}</p>`;
  });
  if(weapon.bayonet){
   const stats=heroAttackStats(hero,weapon.bayonet,0);
   rows.push(`<p>Штык при перезарядке вплотную: ${num(stats.accuracy)}% · ${num(stats.min)}–${num(stats.max)} урона.</p>`);
  }
  return `<div><strong>${slot==='main'?'Основное':'Дополнительное'} · ${esc(weapon.name??ITEMS[weapon.item].name)}</strong>${rows.join('')}</div>`;
 }).join('');
}
function heroStats(h){
 const busy=Boolean(h.job),shown=h.job?.kind==='series'?h.job.worker:h,c=heroConfig(state,shown);
 return `<div class="row">${heroPortrait(h)}<div><h3>${esc(heroTitle(h))} · уровень ${shown.level}</h3><p class="subtitle">${PROFESSIONS[h.profession??'saboteur'].name}${h.nationality?` · ${esc(h.nationality)}`:''} · ${PERKS[h.perk]?.name??'Без стартового перка'}</p></div></div>${health({...h,...(h.job?.kind==='series'?h.job.worker:{}),radiation:(h.radiation??0)+(ready(h.job)?jobRadiation(h.job):0),hp:h.job?.kind==='series'?h.job.worker.hp:isCombatJob(h.job?.kind)&&ready(h.job)?h.job.result.hp:h.hp})}<div class="stats"><div class="stat"><b>${num(c.hero.strength)}</b><small>СИЛА</small></div><div class="stat"><b>${num(c.hero.agility)}</b><small>ЛОВКОСТЬ</small></div><div class="stat"><b>${num(c.hero.intelligence)}</b><small>ИНТЕЛЛЕКТ</small></div><div class="stat"><b>${num(c.hero.perception)}</b><small>ВОСПРИЯТИЕ</small></div></div><div class="badge-row"><span class="pill" title="Бонус перка действует только на дистанции 0">Уклонение ${c.hero.meleeEvasionBonus?`(${num(c.hero.evasion)}% + ${num(c.hero.meleeEvasionBonus)}%)`:num(c.hero.evasion)+'%'}</span><span class="pill">Инициатива ${c.hero.initiative}</span><span class="pill">Точность баз. ${num(c.hero.accuracy)}%</span><span class="pill">Защита физ. ${c.hero.armor}${c.hero.firstHitArmor?' + '+c.hero.firstHitArmor+' на первый урон':''}</span><span class="pill">Защита терм. ${c.hero.thermalArmor}${c.hero.firstHitArmor?' + '+c.hero.firstHitArmor+' на первый урон':''}</span><span class="pill">Защита РАД ${c.hero.radiationProtection}</span>${btn(`Перки за уровни${availablePerkLevels(h).length?` · ${availablePerkLevels(h).length}`:''}`,'levelPerks','','secondary perks-shortcut')}</div>${shown.leaderKebabRuns>0?`<p class="note">Шашлык из Вожака: Сила +2, ещё ${shown.leaderKebabRuns} прохождения.</p>`:''}<div class="hero-combat-stats">${heroCombatStats(c.hero)}<p class="muted">Точность каждого удара и урон до защиты цели. Для стрельбы учтён штраф дистанции.</p></div>${h.wounds?`<div class="warning error">Тяжёлые раны: осталось ${h.wounds} вылазки. −2 к проверкам и −10 п.п. точности.</div>`:''}${busy?'<div class="warning">Сталкер занят. Можно осмотреть снаряжение, но менять его получится после получения результата.</div>':''}<hr class="divider"><div class="tiny-label">СНАРЯЖЕНИЕ</div><div class="equipment">${[['weapon','Основное · любое оружие','knife','main'],['rangedWeapon',heroHasDualWield(h)?'Дополнительное · дальнее / ближнее':'Дополнительное · дистанционное','gun','ranged']].map(([key,label,fallback,slot])=>`<div class="${itemBorder({...h[key+'Details'],item:h[key]})}"><small>${label}</small>${icon(h[key]?ITEMS[h[key]].icon:fallback)}<strong>${h[key]?esc(itemName({...h[key+'Details'],item:h[key]})):key==='rangedWeapon'&&ITEMS[h.weapon]?.twoSlots?'Занято винтовкой':'Не экипировано'}</strong><small>${h[key]?weaponDescription({...h[key+'Details'],item:h[key]},key==='rangedWeapon'&&heroHasDualWield(h))+(ITEMS[h[key]].weaponClass==='pistol'&&h.nationalityBonuses?.pistolDamage?` + ${h.nationalityBonuses.pistolDamage} (национальность)`:''):key==='rangedWeapon'&&ITEMS[h.weapon]?.twoSlots?'Винтовка занимает оба слота':'Выбери оружие в инвентаре'}</small>${h[key]&&!ITEMS[h[key]].twoSlots&&(key==='rangedWeapon'||ITEMS[h[key]].combat==='ranged'||heroHasDualWield(h))?btn(key==='rangedWeapon'?'В основное':'В дополнительное','moveWeapon',`data-slot="${slot}" `+(busy||h.dead?'disabled':''),'secondary'):''}${h[key]?btn('Снять','unequipWeapon',`data-slot="${slot}" `+(busy||h.dead?'disabled':''),'ghost'):''}</div>`).join('')}<div class="${itemBorder({item:h.body,...h.bodyDetails})}">${icon('jacket')}<strong>${h.body?esc(itemName({...h.bodyDetails,item:h.body})):'Без брони'}</strong><small>${h.body?armorDescription({...h.bodyDetails,item:h.body}):'Броню можно изготовить или купить у Юрася'}</small>${h.body?btn('Снять броню','unequip',busy||h.dead?'disabled':'','ghost'):''}</div><div><small>Доп. защита</small>${icon('gasmask')}<strong>${h.accessory?esc(itemName({item:h.accessory,...h.accessoryDetails})):'Не экипировано'}</strong><small>${h.accessory?`Защита РАД +${itemRadiationProtection({item:h.accessory,...h.accessoryDetails})}`:'Плащ РАД-защиты сочетается с бронёй'}</small>${h.accessory?btn('Снять','unequipAccessory',busy||h.dead?'disabled':'','ghost'):''}</div></div><p class="note">Вплотную герой атакует основным оружием. На дистанции — основным, если оно достаёт до цели, иначе дополнительным. Пустой подходящий слот означает пропуск атаки.</p><hr class="divider"><div class="supplies-heading"><div class="tiny-label">РАСХОДНИКИ</div>${btn('Заполнить лечение и гранаты','fillSupplies',busy||h.dead||!bestSuppliesPlan(state,h).length?'disabled':'','secondary supplies-fill')}</div><div class="consumable-slots"><button class="consumable-slot" data-action="medicalSupplies">${icon('medical')}<strong>Лечебное</strong><small>Взято: ${h.bandages+(h.dressingKits??0)+(h.medicKits??0)} / ${consumableLimit(h)}</small></button><button class="consumable-slot" disabled>${icon('stimulant')}<strong>Стимуляторы</strong><small>0 / ${consumableLimit(h)} · Скоро</small></button><button class="consumable-slot" data-action="grenadeSupplies">${icon('grenade')}<strong>Гранаты</strong><small>${(h.grenades??0)+(h.molotovs??0)} / ${consumableLimit(h)}</small></button></div>`;
}
function bonusNotice(h){const bonus=claimBonus(h,h?.job),national=nationalityClaimBonus(h,h?.job),included=h?.job?.kind==='series'?h.job.nationalityBonus??0:0;return (bonus?`<p class="note gold">«Жадный»: дополнительно +${money(bonus)} A при получении.</p>`:'')+(national?`<p class="note gold">Национальность: дополнительно +${money(national)} A.</p>`:'')+(included?`<p class="note gold">В награду серии включён национальный бонус: ${money(included)} A.</p>`:'');}

function repeatButton(h){const job=h?.job;if(!job||!ready(job)||job.special||job.reports?.some(run=>run.special)||radiationBlocksMissions({...h,maxHp:job.worker?.maxHp??h.maxHp,radiation:(h.radiation??0)+jobRadiation(job)})||h.dead||job.worker?.dead||job.kind==='rest'||job.location==='rest'||(isCombatJob(job.kind)&&!job.result.alive))return '';
 const special=activeSpecialLocation(state,job.location??job.kind);
 if(special)return btn(special.name,'repeatHero','data-special="true"','full special-repeat');
 const label=job.kind==='series'
 ?`Повторить ${job.total} ${job.total===5?'раз':'раза'} до ${job.threshold}% HP`
 :'Повторить задание';
 return btn(label+((job.location??job.kind)==='surface'?' · 1 фильтр / выход':''),'repeatHero','','full secondary');}
function seriesButton(kind,h,busy){return btn(kind==='surface'?'Повторять · 1 фильтр / выход':'Повторять','seriesSetup',`data-location="${kind}" data-hero="${esc(h.id)}" `+(busy||h.dead?'disabled':''),'ghost repeat-small');}
function professionPreview(){return `<details class="profession-preview"><summary>Новые профессии</summary><p class="note">Скоро появятся в найме.</p><table class="profession-table"><thead><tr><th>Профессия</th><th title="Сила">СИЛ</th><th title="Ловкость">ЛОВ</th><th title="Интеллект">ИНТ</th><th title="Восприятие">ВОС</th></tr></thead><tbody>${Object.values(PROFESSIONS).filter(p=>!p.available).map(p=>`<tr><th>${p.name}${p.requiredRosterLevel>1?`<small>Герой ${p.requiredRosterLevel}-го уровня</small>`:''}</th><td>${p.strength}</td><td>${p.agility}</td><td>${p.intelligence}</td><td>${p.perception}</td></tr>`).join('')}</tbody></table></details>`;}
function pageHead(kicker,title,subtitle,badge=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${badge}</div>`;}
function station(){return pageHead('Под землёй есть жизнь','Автозаводская','Снаружи — неизвестность. Здесь — точка возвращения.','<button class="btn ghost" data-action="newGameAsk">Всё сначала</button>')+`<div class="scene"><img src="./station.svg" alt="Подземная станция: старый вагон, освещённая лавка и сталкеры на платформе">${stationRole()}<div class="scene-badge"><i></i> АВТОЗАВОДСКАЯ · НА СВЯЗИ</div><div class="scene-caption"><h2>Автозаводская</h2><p>Снарядиться. Найти полезное. Вернуться живым.</p></div></div><div class="columns"><section><div class="section-title"><h2>Твои сталкеры</h2><span>${getHeroes(state).length?String(getHeroes(state).length).padStart(2,'0')+' НА СТАНЦИИ':'ПОКА НИКОГО'}</span></div><div class="card ${rebirthAppearance(state.hero)}">${heroSummary()}</div><div class="quick-grid"><button class="quick" data-action="nav" data-view="production">${icon('tool')}<span><strong>Производство</strong><small>Из мусора — в дело</small></span></button><button class="quick" data-action="nav" data-view="shop">${icon('shop')}<span><strong>Ларёк</strong><small>${state.yuras.visit?'Юрась ждёт тебя':'Проверить полки'}</small></span></button></div></section><section><div class="section-title"><h2>Журнал станции</h2><span>ПОСЛЕДНИЕ СОБЫТИЯ</span></div><div class="card">${state.history.length?state.history.slice(0,4).map(x=>`<div class="log-line"><time>${new Date(x.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time><p>${esc(x.text)}</p></div>`).join(''):`<div class="log-line"><time>СЕЙЧАС</time><p>Ты добрался до станции. Для первой вылазки нужен сталкер.</p></div>`}</div>${keeperCard()}${state.bobrovMet?`<div class="card"><div class="row"><div class="portrait bobrov" aria-hidden="true"><span>★</span></div><div><h3>тов. Бобров</h3><p class="subtitle">Квестовый персонаж</p></div></div><div class="spacer"></div>${btn('Задание Боброва','bobrov','','full secondary')}</div>`:''}</section></div>`;}
function heroes(){
 const all=getHeroes(state),h=state.hero,busy=Boolean(h?.job);
 let content=pageHead('Люди за стенами станции','Сталкеры','Каждый занят своим делом. Станция продолжает жить.');
 const cards=all.map(hero=>`<article class="card hero-card ${rebirthAppearance(hero)} ${hero.id===state.selectedHeroId?'selected':''}" data-hero-card="${esc(hero.id)}">${heroSummary(hero)}</article>`).join('');
 const hireCard=`<div class="card hire-card"><div class="row between"><div><h3>${all.length?'Ещё один сталкер':'Первый сталкер'}</h3><p class="subtitle">Профессия · имя и национальность · перк</p></div>${icon('heroes')}</div><div class="spacer"></div>${btn(`Нанять · ${money(hireCost(state))} A`,'hireModal',state.money<hireCost(state)?'disabled':'','full secondary')}</div>`;

 return content+`<div class="hero-list-layout"><section class="hero-list"><div class="section-title"><h2>На станции: ${all.length}</h2><span>${all.filter(x=>x.job).length} ЗАНЯТО</span></div>${cards}${hireCard}</section></div>`;
}
function locationOccupancy(kind){const owner=locationOwner(state,kind);return owner?`<div class="location-occupant"><div class="portrait small ${owner.dead?'dim':''}" role="img" aria-label="${esc(heroTitle(owner))}"></div><div><strong>Занято · ${esc(heroTitle(owner))}</strong><p>${heroStatus(owner)}. Освободится после получения результата.</p></div></div>`:'';}
const locationIntros={
 mission:'Под станцией скопился мусор. Проверь завалы и будь готов к крысам-мутантам.',
 help:'На станции всегда найдётся работа. Помоги жителям и получи патроны или материалы.',
 patrol:'За постом охраны начинаются тёмные тоннели. Там бродят упыри-разведчики.',
 caravan:CARAVAN.description,
 technopark:TECHNOPARK.description,
 surface:SURFACE.description
};
const firstClearMessages={
 mission:['Рабочий станции','Хорошо, что разобрался с завалами. Возьми фильтр, пригодится.'],
 help:['Юрась','Спасибо за помощь. Держи фильтр от меня.'],
 patrol:['Дежурный поста','Теперь знаем, что в тоннеле. Вот фильтр за разведку.'],
 caravan:['Караванщик','Спасибо, что прошёл с нами. Забирай мои записки.'],
 technopark:['Дурень','Эй, вы чо там? Всех сусликов мне распугали!']
};
function firstLocationResult(hero){
 const job=hero?.job;
 if(!ready(job))return null;
 const location=job.location??job.kind;
 if(location==='surface')return null;
 if(!locationIntros[location]||(location==='technopark'?state.duren:state.completedLocations[location]))return null;
 if(job.kind==='series'&&(job.worker.dead||!job.completed))return null;
 if(isCombatRun(job)&&!job.result.alive)return null;
 return location;
}
function locationBrief(kind){
 if(kind==='surface')return `<p class="note">${SURFACE.description}</p><ul class="schema-note"><li>Потребуется <strong>1 фильтр</strong>.</li><li>Время задания — <strong>20 секунд</strong>.</li><li>Герой пройдёт <strong>четыре проверки</strong>.</li></ul><p class="note">Можно встретить мутировавших собак, Стражей или столкнуться с ловушкой.</p>`;
 const special=activeSpecialLocation(state,kind);
 if(special)return `<p class="note">${special.description}</p>${kind==='mission'?'<p>За победу над королём: 2 золотых зуба, 4–6 металлического мусора, 20 A и 50 опыта.</p>':''}`;
 const combat={mission:[CONFIG.rat,CONFIG.loot,4],patrol:[PATROL.enemy,PATROL.loot,2],technopark:[TECHNOPARK.enemy,TECHNOPARK.loot,4]}[kind];
 if(kind==='caravan')return `<p class="note">${CARAVAN.description}</p><p>Три участка. Шанс нападения по участкам — ${CARAVAN.mission.attackChances.map(chance=>chance+"%").join(", ")}. Караван — 200 HP. При нападении приходят 1–2 Больших Упыря. Если их двое, один атакует героя, другой — караван. В тоннеле можно найти ткань, бутылки и редкие грибы.</p>`;
 if(!combat)return `<p class="note">${locationIntros[kind]} Четыре проверки сложности 8. Можно получить 1–4 A, обрывки ткани и кожи, металлический мусор.</p>`;
 const [enemy,loot,max]=combat;
 const finds=kind==='technopark'?TECHNOPARK.mission.finds:[];
 return `<p class="note">${locationIntros[kind]}</p>${kind==='technopark'?`<p class="radiation-status">Радиация локации — ${TECHNOPARK.radiation} РАД.</p>`: ''}<p>Противников ${kind==='technopark'?1:0}–${max}. ${enemy.name??'Крыса-мутант'} — ${enemy.hp} HP. ${enemy.attackName??'Укус'} наносит ${enemy.damageMin}–${enemy.damageMax} урона.${enemy.rush?` Рывок наносит ${enemy.rush.min}–${enemy.rush.max} урона.`:''}</p><p class="note">Можно найти ${[...loot,...finds].map(x=>ITEMS[x.id].name.toLowerCase()).join(', ')}.</p>`;
}
function locationCard(kind,h){
 const cards={
  surface:{icon:'map',action:'Выйти · 1 фильтр',details:'20 сек. · 1 фильтр · 2–3 РАД',description:'Осмотри магазины, трупы и схроны у выхода. Опасайся стай и растяжек.'},
  mission:{icon:'rat',action:'На вылазку',details:`7 сек. · 4 поиска · ${heroExperience(h,locationExperience(10,h.level,'mission'))}–${heroExperience(h,locationExperience(46,h.level,'mission'))} опыта`,description:'Крысы-мутанты. Куртка и бинты помогут вернуться.'},
  help:{icon:'tool',action:'Помогать',details:`10 сек. · 4 проверки · ${heroExperience(h,locationExperience(5,h.level,'help'))}–${heroExperience(h,locationExperience(17,h.level,'help'))} опыта`,description:'Патроны и материалы за помощь жителям. Без боя.'},
  patrol:{icon:'map',action:'Патрулировать',details:`14 сек. · до 2 упырей · ${heroExperience(h,locationExperience(10,h.level,'patrol'))}–${heroExperience(h,locationExperience(50,h.level,'patrol'))} опыта`,description:'Две проверки восприятия против сложности 8. Трофеи за победу.'},
  caravan:{icon:'bag',action:'Сопроводить',details:'60 сек. · три участка',description:'Сопроводи караван, чтобы все дошли целыми…'},
  technopark:{icon:'station',action:'Исследовать',details:`30 сек. · до 4 Стражей · ${heroExperience(h,locationExperience(35,h.level,'technopark'))}–${heroExperience(h,locationExperience(90,h.level,'technopark'))} опыта`,description:'Суслики проникают сквозь пролом в крыше'}
 };
 const special=activeSpecialLocation(state,kind);
 const card=cards[kind],locked=h.level<LOCATION_LEVELS[kind];
 const combatUnavailable=(isCombatJob(kind)||special)&&!PROFESSIONS[h.profession??'saboteur'].combatReady;
 const disabled=(kind==='surface'&&(state.filters<1||![SURFACE.baseXp,SURFACE.dogXp,SURFACE.guardXp].every(Number.isFinite)))||Boolean(h.job)||h.dead||radiationBlocksMissions(h)||Boolean(locationOwner(state,kind))||locked||combatUnavailable||(kind==='patrol'&&!patrolReady());
 const recent=h.lastCompletedLocation===kind;
 return `<article class="location ${special?'location-special':!disabled&&!state.completedLocations[kind]?'location-first':''}"><div class="row"><div class="location-icon">${icon(card.icon)}</div><div class="grow"><h3>${special?.name??(kind==='surface'&&!state.completedLocations.surface?'Выйти на поверхность и осмотреться':locationName(kind))}</h3><div class="location-meta">${LOCATION_LEVELS[kind]} ур. · ${special?'Особая локация':card.details}${kind==='surface'&&!Number.isFinite(SURFACE.baseXp)?' · уточняются награды':''}</div></div>${recent?'<span class="pill location-recent">Последняя</span>':''}</div><p>${locked?`С уровня ${LOCATION_LEVELS[kind]}. `:''}${special?.description??card.description}</p>${locationOccupancy(kind)}<div class="location-actions">${btn(card.action,kind,`data-hero="${esc(h.id)}" `+(disabled?'disabled':''),'secondary')}${special?'':seriesButton(kind,h,disabled)}</div></article>`;
}
function locations(h){
 if(!h)return '<p class="note">Найми сталкера, чтобы открыть локации.</p>';
 const last=h.lastCompletedLocation;
 const recent=['mission','help','patrol','technopark','caravan','surface'].includes(last)?locationCard(last,h):'';
 const station=['mission','help'].filter(kind=>kind!==last).map(kind=>locationCard(kind,h)).join('');
 const groups=[['underground','Тоннели и станции'],['surface','Поверхность']].map(([area,title])=>{
  const cards=PLANNED_LOCATIONS.filter(x=>x.area===area).map(x=>x.id==='station-surroundings'?(last==='surface'?'':locationCard('surface',h)):x.id==='paveletskaya-caravan'?(last==='caravan'?'':locationCard('caravan',h)):x.id==='technopark'?(last==='technopark'?'':locationCard('technopark',h)):x.id==='tunnel-patrol'?(last==='patrol'?'':locationCard('patrol',h)):`<article class="location planned-location"><div class="row"><div class="location-icon">${icon(x.icon)}</div><h3 class="grow">${esc(x.name)}</h3><span class="pill">Скоро</span></div></article>`).join('');
  return cards?`<div class="section-title location-group"><h2>${title}</h2></div>${cards}`:'';
 }).join('');
 return `<div class="location-list"><p class="subtitle location-hero">Для сталкера: <strong class="gold">${esc(heroTitle(h))}</strong></p>${recent}${station}${groups}</div>`;
}
function upgradeDescription(id){const r=RECIPES[id],target=r.weaponClasses?.includes('shotgun')?'Только дробовики':r.target==='body'?'Любая броня':r.target==='ranged'?'Стрелковое оружие':'Ближнее оружие',effects=[r.blocksAimedShots?'Прицельные выстрелы запрещены (механика появится позже)':null,r.firstHitArmor?`+${r.firstHitArmor} физ. и терм. защиты от первого попадания в каждом бою`:null,r.minBonus!=null?`+${r.minBonus} к минимуму и +${r.maxBonus} к максимуму урона`:null,r.bonus?`+${r.bonus} урона`:null,r.armorBonus?`+${r.armorBonus} физ. защиты`:null,r.thermalArmorBonus?`+${r.thermalArmorBonus} терм. защиты`:null,r.accuracyBonus?`${r.accuracyBonus>0?'+':''}${r.accuracyBonus} п.п. точности`:null,`+${money(upgradeValueBonus(r))} A к ценности`].filter(Boolean);return `${target}: ${effects.join(', ')}. Приписка «${r.prefix}». Успех ${upgradeChance(state,id)}%.${r.replaces?` При успехе заменяет «${RECIPES[r.replaces].name}».`:''}`;}
function armorDescription(row){
 const armor=ITEMS[row.item];
 return `Поглощение: физ. ${itemArmor(row)} · терм. ${itemThermalArmor(row)}${firstHitArmor(row)?` · Ватник +${firstHitArmor(row)} на первый урон`: ''}${armor.radiationProtection?` · РАД +${armor.radiationProtection}`:''}${armor.meleeAccuracyBonus?` · Точность ближнего оружия +${armor.meleeAccuracyBonus} п.п.`:''}${armor.accuracyPenalty?` · Точность любого оружия −${armor.accuracyPenalty} п.п.`:''}`;
}
function itemBorder(row){const quality=itemQuality(row);if(quality)return quality===1?'quality-1':'quality-rare';const tier=itemTier(row);return tier?'tier-'+tier:ITEMS[row?.item]?.rarity==='rare'?'rare-item':'';}
function weaponDescription(row,withoutStrength=false){
 const item=ITEMS[row.item];
 const describe=(stats,type)=>{
  const upgrades=(row.upgrades??[]).filter(u=>!item.bayonet||(RECIPES[u.recipe]?.target??'melee')===type);
  const bonus=upgrades.reduce((n,u)=>n+(u.bonus??0),0),accuracy=upgrades.reduce((n,u)=>n+(u.accuracyBonus??0),0);
  const min=upgrades.reduce((n,u)=>n+(u.minBonus??0),stats.min+10*itemQuality(row)),max=upgrades.reduce((n,u)=>n+(u.maxBonus??0),stats.max+10*itemQuality(row));
  const totalAccuracy=(item.accuracyBonus??0)+accuracy+4*itemQuality(row);
  return `${min}–${max}${type==='melee'&&!withoutStrength?' + Сила × 10':''}${bonus?` + ${bonus} (улучшения)`:''}${totalAccuracy?` · ${totalAccuracy>0?'+':''}${totalAccuracy} п.п. точности`:''}${stats.piercing?' · Пробивающий':''}`;
 };
 return describe(item,item.combat)+(item.bayonet?` · Штык: ${describe(item.bayonet,'melee')}`:item.shots?` × ${item.shots} · −${item.shotPenalty} п.п.`:item.damageRolls?` × ${item.damageRolls} · −${item.shotPenalty} п.п. · дистанция 0–${item.maxDistance}`:item.maxDistance!=null?` · дистанция 0–${item.maxDistance}`:'');
}
